64:       const ny = last.y + ((p.y - last.y) / d) * step;
65:       if (state.ink < step) {
66:         finishLine();
67:         return;
68:       }
69:       state.ink -= step;
70:       pts.push({ x: nx, y: ny });
71:       if (pts.length > 220) finishLine();
72:     },
73:     up() { finishLine(); },
74:     leave() { finishLine(); },
75:   });
76: 
77:   function finishLine() {
78:     if (!state.drawing) return;
79:     const line = state.drawing;
80:     state.drawing = null;
81:     if (line.points.length < 2) return;
82:     state.lines.push({ points: line.points, age: 0 });
83:     audio.splash();
84:   }
85: 
86:   function spawnBee(index) {
87:     const { w, h } = stage;
88:     const fromSide = index % 7 === 4;
89:     let x, y, vx, vy;
90:     if (fromSide) {
91:       const left = index % 2 === 0;
92:       x = left ? -18 : w + 18;
93:       y = rand(h * 0.2, h * 0.5);
94:       vx = (left ? 1 : -1) * rand(70, 120);
95:       vy = rand(-10, 40);
96:     } else {
97:       x = rand(w * 0.12, w * 0.88);
98:       y = -20;
99:       vx = rand(-35, 35);
100:       vy = rand(20, 60);
101:     }
102:     state.bees.push({
103:       x, y, vx, vy,
104:       r: clamp(Math.min(w, h) * 0.019, 9, 14),
105:       phase: rand(0, TAU),
106:       blocked: false,
107:       born: state.time,
108:     });
109:   }
110: 
111:   function burst(x, y, color, amount = 10, power = 150) {
112:     for (let i = 0; i < amount; i++) {
113:       const a = rand(0, TAU);
114:       const sp = rand(power * 0.2, power);
115:       state.particles.push({
116:         x, y,
117:         vx: Math.cos(a) * sp,
118:         vy: Math.sin(a) * sp,
119:         life: rand(0.3, 0.7),
120:         max: 0.7,
121:         size: rand(1.5, 4),
122:         color,
123:       });
124:     }
125:   }
