270:   function drawHeart(ctx, x, y, size, filled) {
271:     ctx.save();
272:     ctx.translate(x, y);
273:     ctx.beginPath();
274:     ctx.moveTo(0, size * 0.32);
275:     ctx.bezierCurveTo(-size * 0.62, -size * 0.18, -size * 0.34, -size * 0.58, 0, -size * 0.25);
276:     ctx.bezierCurveTo(size * 0.34, -size * 0.58, size * 0.62, -size * 0.18, 0, size * 0.32);
277:     ctx.closePath();
278:     if (filled) {
279:       ctx.fillStyle = "#ff5d6c";
280:       ctx.fill();
281:       ctx.strokeStyle = "#20142e";
282:       ctx.lineWidth = 2;
283:       ctx.stroke();
284:     } else {
285:       ctx.strokeStyle = "rgba(255,255,255,0.28)";
286:       ctx.lineWidth = 2;
287:       ctx.stroke();
288:     }
289:     ctx.restore();
290:   }
291: 
292:   function drawBackground(ctx, w, h) {
293:     const sky = ctx.createLinearGradient(0, 0, 0, h);
294:     sky.addColorStop(0, "#ffb36b");
295:     sky.addColorStop(0.35, "#ff8fa3");
296:     sky.addColorStop(0.7, "#9b4d8f");
297:     sky.addColorStop(1, "#4a2360");
298:     ctx.fillStyle = sky;
299:     ctx.fillRect(0, 0, w, h);
300: 
301:     // sun
302:     ctx.save();
303:     ctx.globalAlpha = 0.9;
304:     const sun = ctx.createRadialGradient(w * 0.74, h * 0.17, 4, w * 0.74, h * 0.17, w * 0.24);
305:     sun.addColorStop(0, "#fff6c9");
306:     sun.addColorStop(0.4, "#ffe27a");
307:     sun.addColorStop(1, "rgba(255, 210, 63, 0)");
308:     ctx.fillStyle = sun;
309:     ctx.beginPath();
310:     ctx.arc(w * 0.74, h * 0.17, w * 0.24, 0, TAU);
311:     ctx.fill();
312:     ctx.restore();
313: 
314:     // clouds
315:     drawSprite(ctx, "cloud", w * 0.18, h * 0.12, w * 0.3, { alpha: 0.65 });
316:     drawSprite(ctx, "cloud", w * 0.86, h * 0.25, w * 0.22, { alpha: 0.45 });
317:     drawSprite(ctx, "cloud", w * 0.4, h * 0.06, w * 0.18, { alpha: 0.35 });
318: 
319:     // hills
320:     const hill1 = ctx.createLinearGradient(0, h * 0.6, 0, h);
321:     hill1.addColorStop(0, "#4e8f68");
322:     hill1.addColorStop(1, "#2d5e48");
323:     ctx.fillStyle = hill1;
324:     ctx.beginPath();
325:     ctx.moveTo(0, h * 0.72);
326:     ctx.quadraticCurveTo(w * 0.25, h * 0.58, w * 0.52, h * 0.7);
327:     ctx.quadraticCurveTo(w * 0.8, h * 0.82, w, h * 0.64);
328:     ctx.lineTo(w, h);
329:     ctx.lineTo(0, h);
330:     ctx.closePath();
331:     ctx.fill();
332: 
333:     const hill2 = ctx.createLinearGradient(0, h * 0.75, 0, h);
334:     hill2.addColorStop(0, "#3f7d59");
335:     hill2.addColorStop(1, "#224b39");
336:     ctx.fillStyle = hill2;
337:     ctx.beginPath();
338:     ctx.moveTo(0, h * 0.85);
339:     ctx.quadraticCurveTo(w * 0.3, h * 0.76, w * 0.58, h * 0.86);
340:     ctx.quadraticCurveTo(w * 0.8, h * 0.93, w, h * 0.84);
341:     ctx.lineTo(w, h);
342:     ctx.lineTo(0, h);
343:     ctx.closePath();
344:     ctx.fill();
345: 
346:     // bushes and flowers
347:     drawSprite(ctx, "bush", w * 0.06, h * 0.78, w * 0.2, { alpha: 0.9 });
348:     drawSprite(ctx, "bush", w * 0.96, h * 0.84, w * 0.17, { alpha: 0.85 });
349:     for (let i = 0; i < 5; i++) {
350:       drawSprite(ctx, "flower", w * (0.12 + i * 0.19), h * (0.9 + (i % 2) * 0.035), w * 0.05, { alpha: 0.85 });
351:     }
352: 
353:     // sunbeam haze
354:     ctx.save();
355:     ctx.globalAlpha = 0.08;
356:     ctx.fillStyle = "#fff";
357:     ctx.beginPath();
358:     ctx.moveTo(w * 0.74, h * 0.17);
359:     ctx.lineTo(w * 0.4, h);
360:     ctx.lineTo(w * 0.58, h);
361:     ctx.lineTo(w * 0.82, h * 0.2);
362:     ctx.closePath();
363:     ctx.fill();
364:     ctx.restore();
365:   }
