367:   function drawLines(ctx) {
368:     for (const line of state.lines) {
369:       const pts = line.points;
370:       const alpha = line.age > LINE_LIFE - 2 ? clamp((LINE_LIFE - line.age) / 2, 0, 1) : 1;
371:       ctx.save();
372:       ctx.globalAlpha = alpha;
373:       ctx.lineCap = "round";
374:       ctx.lineJoin = "round";
375:       ctx.strokeStyle = "rgba(255, 196, 61, 0.26)";
376:       ctx.lineWidth = LINE_WIDTH + 8;
377:       ctx.beginPath();
378:       pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
379:       ctx.stroke();
380: 
381:       const grad = ctx.createLinearGradient(0, 0, 0, stage.h);
382:       grad.addColorStop(0, "#ffe89c");
383:       grad.addColorStop(0.5, "#ffc93f");
384:       grad.addColorStop(1, "#ff9f1a");
385:       ctx.strokeStyle = grad;
386:       ctx.lineWidth = LINE_WIDTH;
387:       ctx.beginPath();
388:       pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
389:       ctx.stroke();
390: 
391:       ctx.strokeStyle = "rgba(255,255,255,0.55)";
392:       ctx.lineWidth = 2.2;
393:       ctx.beginPath();
394:       pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y - 1) : ctx.moveTo(p.x, p.y - 1); });
395:       ctx.stroke();
396:       ctx.restore();
397:     }
398: 
399:     if (state.drawing) {
400:       const pts = state.drawing.points;
401:       ctx.save();
402:       ctx.lineCap = "round";
403:       ctx.lineJoin = "round";
404:       ctx.strokeStyle = "rgba(255, 201, 63, 0.9)";
405:       ctx.lineWidth = LINE_WIDTH;
406:       ctx.beginPath();
407:       pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
408:       ctx.stroke();
409:       const end = pts[pts.length - 1];
410:       ctx.fillStyle = "#fff4c2";
411:       ctx.beginPath();
412:       ctx.arc(end.x, end.y, LINE_WIDTH * 0.55, 0, TAU);
413:       ctx.fill();
414:       ctx.restore();
415:     }
416:   }
