418:   function drawDog(ctx, w, h) {
419:     const d = dog();
420:     const bob = Math.sin(state.time * 2.4) * 2;
421:     const flash = state.dogFlash > 0 && Math.floor(state.time * 18) % 2 === 0;
422: 
423:     ctx.save();
424:     ctx.fillStyle = "rgba(20, 10, 30, 0.22)";
425:     ctx.beginPath();
426:     ctx.ellipse(d.x, d.y + d.size * 0.37, d.size * 0.3, d.size * 0.07, 0, 0, TAU);
427:     ctx.fill();
428: 
429:     if (state.phase === "won") {
430:       const t = Math.min(1, state.winT / 0.8);
431:       ctx.translate(d.x, d.y - easeOutCubic(t) * 32 + bob);
432:       ctx.scale(1 + Math.sin(state.winT * 8) * 0.03, 1 + Math.sin(state.winT * 8) * 0.03);
433:       drawSprite(ctx, "dog", 0, 0, d.size, { alpha: flash ? 0.55 : 1 });
434:     } else {
435:       drawSprite(ctx, "dog", d.x, d.y + bob, d.size, {
436:         alpha: flash ? 0.55 : 1,
437:         rot: state.dogFlash * 0.04 * Math.sin(state.time * 40),
438:       });
439:     }
440:     ctx.restore();
441: 
442:     // speech bubble
443:     if (state.bubble.life > 0) {
444:       const a = clamp(state.bubble.life, 0, 1);
445:       const text = state.bubble.text;
446:       ctx.save();
447:       ctx.globalAlpha = a;
448:       ctx.font = `900 ${Math.round(clamp(w * 0.042, 13, 18))}px ${DISPLAY}`;
449:       const tw = ctx.measureText(text).width;
450:       const bw = tw + 22;
451:       const bh = 30;
452:       const bx = clamp(d.x + d.size * 0.24, 10, w - bw - 10);
453:       const by = d.y - d.size * 0.72;
454:       ctx.fillStyle = "#fff8ee";
455:       ctx.strokeStyle = "#20142e";
456:       ctx.lineWidth = 2.5;
457:       roundRect(ctx, bx, by, bw, bh, 11);
458:       ctx.fill();
459:       ctx.stroke();
460:       ctx.beginPath();
461:       ctx.moveTo(bx + 12, by + bh - 1);
462:       ctx.lineTo(bx + 4, by + bh + 10);
463:       ctx.lineTo(bx + 24, by + bh - 1);
464:       ctx.closePath();
465:       ctx.fillStyle = "#fff8ee";
466:       ctx.fill();
467:       ctx.stroke();
468:       ctx.fillStyle = "#20142e";
469:       ctx.textAlign = "center";
470:       ctx.textBaseline = "middle";
471:       ctx.fillText(text, bx + bw / 2, by + bh / 2 + 1);
472:       ctx.restore();
473:     }
474:   }
