476:   function drawBees(ctx) {
477:     for (const bee of state.bees) {
478:       const flap = Math.sin(state.time * 28 + bee.phase);
479:       ctx.save();
480:       ctx.translate(bee.x, bee.y);
481:       ctx.rotate(clamp(bee.vx * 0.004, -0.3, 0.3) + Math.sin(state.time * 7 + bee.phase) * 0.08);
482:       ctx.globalAlpha = 0.18;
483:       ctx.fillStyle = "#20142e";
484:       ctx.beginPath();
485:       ctx.ellipse(0, bee.r + 8, bee.r * 0.75, 3, 0, 0, TAU);
486:       ctx.fill();
487:       ctx.globalAlpha = 1;
488:       drawSprite(ctx, "bee", 0, 0, bee.r * 2.9, { flipY: flap < 0 });
489:       ctx.restore();
490:     }
491:   }
