493:   function drawHud(ctx, w, h) {
494:     const pad = 12;
495:     const top = 10;
496:     // hearts
497:     ctx.save();
498:     ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
499:     roundRect(ctx, pad, top, 104, 32, 10);
500:     ctx.fill();
501:     for (let i = 0; i < 3; i++) {
502:       drawHeart(ctx, pad + 19 + i * 26, top + 16, 18, i < state.hearts);
503:     }
504:     ctx.restore();
505: 
506:     // timer
507:     ctx.save();
508:     const timeLeft = Math.max(0, DURATION - state.time);
509:     ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
510:     roundRect(ctx, w - pad - 62, top, 62, 32, 10);
511:     ctx.fill();
512:     ctx.fillStyle = timeLeft < 5 ? "#ffd23f" : "#fff";
513:     ctx.font = `900 15px ${DISPLAY}`;
514:     ctx.textAlign = "center";
515:     ctx.textBaseline = "middle";
516:     ctx.fillText(`${timeLeft.toFixed(1)}s`, w - pad - 31, top + 17);
517:     ctx.restore();
518: 
519:     // ink bar
520:     const barW = clamp(w * 0.32, 100, 140);
521:     const barX = w / 2 - barW / 2;
522:     const barY = top + 12;
523:     ctx.save();
524:     ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
525:     roundRect(ctx, barX - 8, top, barW + 16, 32, 10);
526:     ctx.fill();
527:     ctx.fillStyle = "rgba(255,255,255,0.14)";
528:     roundRect(ctx, barX, barY, barW, 8, 4);
529:     ctx.fill();
530:     const pct = state.ink / state.maxInk;
531:     const grad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
532:     grad.addColorStop(0, "#ffe89c");
533:     grad.addColorStop(1, "#ff9f1a");
534:     ctx.fillStyle = grad;
535:     roundRect(ctx, barX, barY, Math.max(2, barW * pct), 8, 4);
536:     ctx.fill();
537:     ctx.fillStyle = "rgba(255,255,255,0.55)";
538:     ctx.font = `900 6.5px ${DISPLAY}`;
539:     ctx.textAlign = "center";
540:     ctx.fillText("HONEY INK", w / 2, top + 27);
541:     ctx.restore();
542:   }
