238:     let best = Infinity;
239:     for (const e of state.enemies) {
240:       if (e.dead) continue;
241:       const d = dist(p.x, p.y, e.x, e.y);
242:       if (d < best) { best = d; target = e; }
243:     }
244:     if (target) {
245:       const desired = Math.atan2(target.y - p.y, target.x - p.x);
246:       p.aim = rotateToward(p.aim, desired, 14 * 0.016);
247:     }
248:     const spread = 0.11;
249:     const count = state.multishot;
250:     for (let i = 0; i < count; i++) {
251:       const offset = (i - (count - 1) / 2) * spread;
252:       const a = p.aim + offset + rand(-0.018, 0.018);
253:       const speed = 570;
254:       state.bullets.push({
255:         x: p.x + Math.cos(a) * 24,
256:         y: p.y + Math.sin(a) * 24,
257:         px: p.x + Math.cos(a) * 24,
258:         py: p.y + Math.sin(a) * 24,
259:         vx: Math.cos(a) * speed,
260:         vy: Math.sin(a) * speed,
261:         life: 1.15,
262:         damage: state.damage,
263:         hits: 0,
264:         maxHits: state.pierce + 1,
265:         hitSet: new Set(),
266:         angle: a,
267:       });
268:     }
269:     burst(p.x + Math.cos(p.aim) * 28, p.y + Math.sin(p.aim) * 28, "#ffe89c", 3, 100);
270:     state.fireTimer = state.fireInterval;
271:     audio.shoot();
272:     if (target) p.aim = Math.atan2(target.y - p.y, target.x - p.x);
273:   }
274: 
275:   function killEnemy(enemy) {
276:     enemy.dead = true;
277:     state.kills++;
278:     burst(enemy.x, enemy.y, enemy.elite ? "#ffd23f" : "#9b5cff", enemy.elite ? 22 : 12, 220);
279:     audio.pop();
280:     if (Math.random() < (enemy.elite ? 1 : 0.9)) {
281:       state.gems.push({
282:         x: enemy.x,
283:         y: enemy.y,
284:         vx: rand(-30, 30),
285:         vy: rand(-40, 10),
286:         value: enemy.elite ? 3 : 1,
287:         phase: rand(0, TAU),
288:       });
289:     }
290:   }
291: 
292:   function damagePlayer(amount) {
293:     const p = state.player;
294:     if (p.inv > 0 || state.phase !== "play") return;
295:     p.hp -= amount;
296:     p.inv = 1.0;
297:     p.hitFlash = 1;
298:     state.redFlash = 1;
299:     state.shake = 8;
300:     addFloat(`-${amount}`, "#ff5d6c", p.x, p.y - 30, 0.8);
301:     audio.hurt();
302:     api.vibrate?.([25, 25, 45]);
303:     if (p.hp <= 0) {
304:       p.hp = 0;
305:       state.phase = "dead";
306:       state.deadT = 0;
307:       burst(p.x, p.y, "#ff5d6c", 34, 260);
308:       audio.lose();
309:       setTimeout(() => {
310:         if (!state.ended) {
311:           state.ended = true;
312:           api.lose(`You survived ${state.time.toFixed(1)}s and got ${state.kills} kills. HP: 0.`);
313:         }
314:       }, 950);
315:     }
316:   }
317: 
318:   function chooseStart() {
319:     // collect xp and trigger upgrade when earned
320:     if (state.xp >= state.xpNext) levelUp();
321:   }
322: 
323:   function update(dt) {
324:     state.time += dt;
325:     state.intro = Math.max(0, state.intro - dt);
326:     state.shake = Math.max(0, state.shake - dt * 26);
327:     state.redFlash = Math.max(0, state.redFlash - dt * 3);
328:     state.levelFlash = Math.max(0, state.levelFlash - dt);
329: 
330:     const p = state.player;
331:     p.inv = Math.max(0, p.inv - dt);
332:     p.hitFlash = Math.max(0, p.hitFlash - dt * 2.5);
333: 
334:     if (state.phase !== "play") {
335:       if (state.phase === "dead") state.deadT += dt;
336:       if (state.phase === "won") state.winT += dt;
337:     } else {
338:       if (state.time >= SURVIVE && !state.ended) {
339:         state.phase = "won";
340:         state.winT = 0;
341:         state.ended = true;
342:         audio.win();
343:         const stars = p.hp >= 80 ? 3 : p.hp >= 50 ? 2 : 1;
344:         setTimeout(() => {
345:           api.win(stars, state.kills, {
346:             note: `Survived 30 seconds with ${Math.round(p.hp)} HP and ${state.kills} kills. The island is safer, allegedly.`,
347:           });
348:         }, 800);
349:       }
350: 
351:       // movement
352:       let mx = 0;
353:       let my = 0;
354:       if (input.isDown("arrowleft", "a")) mx -= 1;
355:       if (input.isDown("arrowright", "d")) mx += 1;
356:       if (input.isDown("arrowup", "w")) my -= 1;
357:       if (input.isDown("arrowdown", "s")) my += 1;
358:       if (mx || my) {
359:         const l = Math.hypot(mx, my);
360:         mx /= l; my /= l;
361:       } else if (state.joystick.active) {
362:         const l = Math.hypot(state.joystick.dx, state.joystick.dy);
363:         if (l > 4) {
364:           mx = state.joystick.dx / l;
365:           my = state.joystick.dy / l;
366:         }
367:       }
368:       const speed = clamp(Math.min(stage.w, stage.h) * 0.4, 140, 200) * state.speedMult;
369:       p.x = clamp(p.x + mx * speed * dt, 28, stage.w - 28);
370:       p.y = clamp(p.y + my * speed * dt, 64, stage.h - 30);
371:       if (mx || my) burst(p.x, p.y + 16, "rgba(62,233,165,0.25)", 1, 30);
372: 
373:       // auto-fire
374:       state.fireTimer -= dt;
375:       if (state.fireTimer <= 0) shoot();
376: 
377:       // spawn
378:       state.spawnTimer -= dt;
379:       if (state.spawnTimer <= 0) {
380:         const interval = Math.max(0.3, 0.85 - state.time * 0.018);
381:         state.spawnTimer = interval * rand(0.75, 1.15);
382:         spawnEnemy();
383:         if (state.time > 18 && Math.random() < 0.4) spawnEnemy();
384:         if (state.time > 26 && Math.random() < 0.45) spawnEnemy();
385:       }
386: 
387:       // enemies chase
388:       for (const e of state.enemies) {
389:         if (e.dead) continue;
390:         e.phase += dt;
391:         e.biteCd = Math.max(0, e.biteCd - dt);
392:         e.hit = Math.max(0, e.hit - dt * 8);
393:         const dx = p.x - e.x;
394:         const dy = p.y - e.y;
395:         const d = Math.hypot(dx, dy) || 1;
396:         e.x += (dx / d) * e.speed * dt + e.kbx * dt;
397:         e.y += (dy / d) * e.speed * dt + e.kby * dt;
398:         e.kbx *= 1 - dt * 8;
399:         e.kby *= 1 - dt * 8;
400:         if (d < e.r + 18 && e.biteCd <= 0) {
401:           damagePlayer(e.elite ? 14 : 9);
402:           e.biteCd = 1.4;
403:           e.kbx = -(dx / d) * 160;
404:           e.kby = -(dy / d) * 160;
405:         }
406:       }
407: 
408:       // separation (keeps the horde readable)
409:       for (let i = 0; i < state.enemies.length; i++) {
410:         const a = state.enemies[i];
411:         if (a.dead) continue;
412:         for (let j = i + 1; j < state.enemies.length; j++) {
413:           const b = state.enemies[j];
414:           if (b.dead) continue;
415:           const dx = b.x - a.x;
416:           const dy = b.y - a.y;
417:           const dd = Math.hypot(dx, dy) || 1;
418:           const overlap = a.r + b.r - dd;
419:           if (overlap > 0 && dd < a.r + b.r) {
420:             const push = overlap * 0.5;
421:             const nx = dx / dd;
422:             const ny = dy / dd;
423:             a.x -= nx * push * 0.5;
424:             a.y -= ny * push * 0.5;
425:             b.x += nx * push * 0.5;
426:             b.y += ny * push * 0.5;
427:           }
428:         }
429:       }
430: 
431:       // bullets
432:       for (const b of state.bullets) {
433:         b.px = b.x;
434:         b.py = b.y;
435:         b.x += b.vx * dt;
436:         b.y += b.vy * dt;
437:         b.life -= dt;
438:         for (const e of state.enemies) {
439:           if (e.dead || b.hitSet.has(e.id)) continue;
440:           if (dist(b.x, b.y, e.x, e.y) < e.r + 4) {
441:             b.hitSet.add(e.id);
442:             e.hp -= b.damage;
443:             e.hit = 1;
444:             e.kbx += b.vx * 0.08;
445:             e.kby += b.vy * 0.08;
446:             burst(b.x, b.y, "#ffe89c", 4, 95);
447:             b.hits++;
448:             if (e.hp <= 0) killEnemy(e);
449:             if (b.hits >= b.maxHits) { b.life = 0; break; }
450:           }
451:         }
452:       }
453:       state.bullets = state.bullets.filter((b) => b.life > 0 && b.x > -30 && b.x < stage.w + 30 && b.y > -30 && b.y < stage.h + 30);
454:       state.enemies = state.enemies.filter((e) => !e.dead);
455: 
456:       // gems
457:       for (const g of state.gems) {
458:         g.phase += dt;
459:         g.vx *= 1 - dt * 1.6;
460:         g.vy *= 1 - dt * 1.6;
461:         g.x += g.vx * dt;
462:         g.y += g.vy * dt;
463:         const dx = p.x - g.x;
464:         const dy = p.y - g.y;
465:         const d = Math.hypot(dx, dy) || 1;
466:         if (d < state.magnet) {
467:           const pull = clamp((state.magnet - d) * 5.5, 60, 900);
468:           g.x += (dx / d) * pull * dt;
469:           g.y += (dy / d) * pull * dt;
470:         }
471:         if (d < 22) {
472:           g.dead = true;
473:           state.xp += g.value;
474:           audio.eat();
475:           burst(g.x, g.y, "#62e8ff", 5, 100);
476:           chooseStart();
477:         }
478:       }
479:       state.gems = state.gems.filter((g) => !g.dead && g.y < stage.h + 60);
480:     }
481: 
482:     // particles / floats
483:     for (const part of state.particles) {
484:       part.life -= dt;
485:       part.x += part.vx * dt;
486:       part.y += part.vy * dt;
487:       part.vx *= 1 - dt * 1.4;
488:       part.vy *= 1 - dt * 1.4;
489:     }
490:     state.particles = state.particles.filter((part) => part.life > 0);
491: 
492:     for (const f of state.floats) {
493:       f.life -= dt;
494:       f.y -= 32 * dt;
495:     }
496:     state.floats = state.floats.filter((f) => f.life > 0);
497: 
498:     state.bullets = state.bullets.filter((b) => b.life > 0);
499:   }
500: 
501:   function drawArena(ctx, w, h) {
502:     const g = ctx.createLinearGradient(0, 0, 0, h);
503:     g.addColorStop(0, "#0d2a26");
504:     g.addColorStop(0.55, "#0a1f1c");
505:     g.addColorStop(1, "#061412");
506:     ctx.fillStyle = g;
507:     ctx.fillRect(0, 0, w, h);
508: 
509:     // dirt patches
510:     ctx.save();
511:     for (let i = 0; i < 9; i++) {
512:       const x = ((i * 167 + 40) % w);
513:       const y = ((i * 211 + 30) % h);
514:       ctx.globalAlpha = 0.15;
515:       ctx.fillStyle = i % 2 ? "#4b6b3f" : "#223f35";
516:       ctx.beginPath();
517:       ctx.ellipse(x, y, 40 + (i % 3) * 22, 18 + (i % 2) * 9, i, 0, TAU);
518:       ctx.fill();
519:     }
520:     ctx.restore();
521: 
522:     // grass tufts
523:     ctx.save();
524:     ctx.strokeStyle = "rgba(87, 183, 121, 0.3)";
525:     ctx.lineWidth = 1.4;
526:     for (let i = 0; i < 44; i++) {
527:       const x = ((i * 97.3) % w);
528:       const y = ((i * 173.7 + 15) % h);
529:       ctx.beginPath();
530:       ctx.moveTo(x, y);
531:       ctx.quadraticCurveTo(x + 3, y - 6, x + 6, y - 9);
532:       ctx.moveTo(x + 3, y);
533:       ctx.quadraticCurveTo(x + 2, y - 7, x - 1, y - 10);
534:       ctx.stroke();
535:     }
536:     ctx.restore();
537: 
538:     // fireflies
539:     for (let i = 0; i < 10; i++) {
540:       const x = ((i * 113 + Math.sin(state.time * 0.35 + i) * 24) % (w + 20)) - 10;
541:       const y = ((i * 79 + Math.cos(state.time * 0.3 + i * 2) * 18) % (h + 20)) - 10;
542:       ctx.globalAlpha = 0.25 + Math.sin(state.time * 2 + i) * 0.18;
543:       ctx.fillStyle = "#b9ffb0";
544:       ctx.beginPath();
545:       ctx.arc(x, y, 1.4, 0, TAU);
546:       ctx.fill();
547:     }
548:     ctx.globalAlpha = 1;
549: 
550:     const vign = ctx.createRadialGradient(w / 2, h / 2, h * 0.22, w / 2, h / 2, h * 0.8);
551:     vign.addColorStop(0, "rgba(0,0,0,0)");
552:     vign.addColorStop(1, "rgba(0,0,0,0.46)");
553:     ctx.fillStyle = vign;
554:     ctx.fillRect(0, 0, w, h);
555:   }
556: 
557:   function drawEnemies(ctx) {
558:     for (const e of state.enemies) {
559:       const bob = Math.sin(state.time * 4 + e.phase) * 2;
560:       const squash = 1 + Math.sin(state.time * 6 + e.phase) * 0.045;
561:       const size = e.r * 2.7;
562:       ctx.save();
563:       ctx.fillStyle = "rgba(0,0,0,0.26)";
564:       ctx.beginPath();
565:       ctx.ellipse(e.x, e.y + e.r * 1.2, e.r * 0.85, e.r * 0.24, 0, 0, TAU);
566:       ctx.fill();
567:       if (e.elite) {
568:         ctx.globalAlpha = 0.35 + Math.sin(state.time * 4 + e.phase) * 0.12;
569:         ctx.strokeStyle = "#ffd23f";
570:         ctx.lineWidth = 2;
571:         ctx.beginPath();
572:         ctx.arc(e.x, e.y, e.r + 7, 0, TAU);
573:         ctx.stroke();
574:         ctx.globalAlpha = 1;
575:       }
576:       ctx.translate(e.x, e.y + bob);
577:       ctx.scale(1 / squash, squash);
578:       if (e.hit > 0) {
579:         ctx.globalAlpha = 0.55 + 0.45 * Math.sin(e.hit * 30);
580:       }
581:       drawSprite(ctx, "slime", 0, 0, size, { rot: Math.sin(state.time * 2.4 + e.phase) * 0.05 });
582:       ctx.restore();
583: 
584:       if (e.hp < e.maxHp || e.elite) {
585:         const bw = Math.max(22, e.r * 1.8);
586:         const bx = e.x - bw / 2;
587:         const by = e.y - e.r * 1.55;
588:         ctx.fillStyle = "rgba(0,0,0,0.45)";
589:         roundRect(ctx, bx, by, bw, 4, 2);
590:         ctx.fill();
591:         const pct = clamp(e.hp / e.maxHp, 0, 1);
592:         ctx.fillStyle = e.elite ? "#ffd23f" : "#3ee9a5";
593:         roundRect(ctx, bx, by, bw * pct, 4, 2);
594:         ctx.fill();
595:       }
596:     }
597:   }
598: 
599:   function drawGems(ctx) {
600:     for (const g of state.gems) {
601:       const bob = Math.sin(state.time * 4 + g.phase) * 3;
602:       const s = g.value > 1 ? 24 : 18;
603:       ctx.save();
604:       ctx.shadowColor = "rgba(98,232,255,0.65)";
605:       ctx.shadowBlur = 12;
606:       drawSprite(ctx, "gem", g.x, g.y + bob, s, { rot: Math.sin(state.time * 2 + g.phase) * 0.16 });
607:       ctx.restore();
608:     }
609:   }
610: 
611:   function drawBullets(ctx) {
612:     for (const b of state.bullets) {
613:       ctx.save();
614:       ctx.strokeStyle = "rgba(255, 232, 156, 0.4)";
615:       ctx.lineWidth = 5;
616:       ctx.lineCap = "round";
617:       ctx.beginPath();
618:       ctx.moveTo(b.px, b.py);
619:       ctx.lineTo(b.x, b.y);
