635:   function drawPlayer(ctx) {
636:     const p = state.player;
637:     const flicker = p.inv > 0 && Math.floor(state.time * 18) % 2 === 0;
638:     ctx.save();
639:     ctx.fillStyle = "rgba(0,0,0,0.28)";
