656:       ctx.fillStyle = "rgba(255,255,255,0.6)";
657:       ctx.beginPath();
658:       ctx.arc(mx, my, 2.4, 0, TAU);
659:       ctx.fill();
660:     }
661:     ctx.restore();
662:   }
