719:     roundRect(ctx, pad + 8, xpY, Math.max(2, (xpW - 16) * xpPct), 5, 3);
720:     ctx.fill();
721:     ctx.fillStyle = "#fff";
722:     ctx.font = `900 7.5px ${DISPLAY}`;
723:     ctx.textAlign = "left";
724:     ctx.fillText(`LV ${state.level}`, pad + 10, xpY - 11);
