731:   function draw() {
732:     const { ctx } = stage;
733:     const w = stage.w;
734:     const h = stage.h;
735:     ctx.save();
736:     if (state.shake > 0.1) ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
737: 
738:     drawArena(ctx, w, h);
739:     drawGems(ctx);
740:     drawEnemies(ctx);
741:     drawBullets(ctx);
742:     drawPlayer(ctx);
743: 
744:     for (const part of state.particles) {
745:       const a = clamp(part.life / part.max, 0, 1);
746:       ctx.globalAlpha = a;
747:       ctx.fillStyle = part.color;
748:       ctx.beginPath();
749:       ctx.arc(part.x, part.y, part.size, 0, TAU);
750:       ctx.fill();
751:     }
752:     ctx.globalAlpha = 1;
753: 
754:     for (const f of state.floats) {
755:       const a = clamp(f.life / f.max, 0, 1);
