63:       const nx = last.x + ((p.x - last.x) / d) * step;
64:       const ny = last.y + ((p.y - last.y) / d) * step;
65:       if (state.ink < step) {
66:         finishLine();
67:         return;
68:       }
69:       state.ink -= step;
70:       pts.push({ x: nx, y: ny });
71:       if (pts.length > 220) finishLine();
72:     },
73:     up() { finishLine(); },
74:     leave() { finishLine(); },
75:   });
