77:   function finishLine() {
78:     if (!state.drawing) return;
79:     const line = state.drawing;
80:     state.drawing = null;
81:     if (line.points.length < 2) return;
82:     state.lines.push({ points: line.points, age: 0 });
83:     audio.splash();
84:   }
