86:   function spawnBee(index) {
87:     const { w, h } = stage;
88:     const fromSide = index % 7 === 4;
89:     let x, y, vx, vy;
90:     if (fromSide) {
91:       const left = index % 2 === 0;
92:       x = left ? -18 : w + 18;
93:       y = rand(h * 0.2, h * 0.5);
94:       vx = (left ? 1 : -1) * rand(70, 120);
95:       vy = rand(-10, 40);
96:     } else {
97:       x = rand(w * 0.12, w * 0.88);
98:       y = -20;
99:       vx = rand(-35, 35);
100:       vy = rand(20, 60);
101:     }
102:     state.bees.push({
103:       x, y, vx, vy,
104:       r: clamp(Math.min(w, h) * 0.019, 9, 14),
105:       phase: rand(0, TAU),
106:       blocked: false,
107:       born: state.time,
108:     });
109:   }
