111:   function burst(x, y, color, amount = 10, power = 150) {
112:     for (let i = 0; i < amount; i++) {
113:       const a = rand(0, TAU);
114:       const sp = rand(power * 0.2, power);
115:       state.particles.push({
116:         x, y,
117:         vx: Math.cos(a) * sp,
118:         vy: Math.sin(a) * sp,
119:         life: rand(0.3, 0.7),
120:         max: 0.7,
121:         size: rand(1.5, 4),
122:         color,
123:       });
124:     }
125:   }
