127:   function hitDog(bee) {
128:     const d = dog();
129:     state.hearts--;
130:     state.dogFlash = 1;
131:     state.shake = 10;
132:     state.flash = 0.8;
133:     state.bubble = { text: state.hearts > 0 ? "OUCH!" : "NOOO!", life: 1.6 };
134:     burst(d.x, d.y - d.size * 0.2, "#ff5d6c", 24, 220);
135:     audio.hurt();
136:     api.vibrate?.([25, 30, 50]);
137:     if (state.hearts <= 0 && state.phase === "play") {
138:       state.phase = "lost";
139:       state.loseT = 0;
140:       setTimeout(() => {
141:         if (!state.ended) {
142:           state.ended = true;
143:           api.lose("The bees got the dog. The dog has filed a formal complaint.");
144:         }
145:       }, 1000);
146:     }
