149:   function collideLines(bee) {
150:     if (bee.y > stage.h + 30) return;
151:     for (const line of state.lines) {
152:       if (line.age > LINE_LIFE - 0.8) continue;
153:       const pts = line.points;
154:       for (let i = 0; i < pts.length - 1; i++) {
155:         const a = pts[i];
156:         const b = pts[i + 1];
157:         const abx = b.x - a.x;
158:         const aby = b.y - a.y;
159:         const len2 = abx * abx + aby * aby || 1;
160:         let t = ((bee.x - a.x) * abx + (bee.y - a.y) * aby) / len2;
161:         t = clamp(t, 0, 1);
162:         const px = a.x + abx * t;
163:         const py = a.y + aby * t;
164:         const dx = bee.x - px;
165:         const dy = bee.y - py;
166:         const dd = Math.hypot(dx, dy);
167:         const target = bee.r + LINE_WIDTH / 2;
168:         if (dd < target && dd > 0.001) {
169:           const nx = dx / dd;
170:           const ny = dy / dd;
171:           bee.x = px + nx * target;
172:           bee.y = py + ny * target;
173:           const vn = bee.vx * nx + bee.vy * ny;
174:           if (vn < 0) {
175:             bee.vx -= 1.55 * vn * nx;
176:             bee.vy -= 1.55 * vn * ny;
177:           }
178:           const tangent = (Math.random() - 0.5) * 90;
179:           bee.vx += -ny * tangent * 0.35;
180:           bee.vy += nx * tangent * 0.35;
181:           if (!bee.blocked) {
182:             bee.blocked = true;
183:             state.blocked++;
184:             state.tickle = 0.5;
185:           }
186:           if (state.time - (bee.lastSound || 0) > 0.18) {
187:             bee.lastSound = state.time;
188:             audio.tick();
189:           }
190:         }
191:       }
192:     }
193:   }
