195:   function update(dt) {
196:     state.time += dt;
197:     state.shake = Math.max(0, state.shake - dt * 24);
198:     state.flash = Math.max(0, state.flash - dt * 2.6);
199:     state.dogFlash = Math.max(0, state.dogFlash - dt * 2.2);
200:     state.tickle = Math.max(0, state.tickle - dt);
201: 
202:     if (state.bubble.life > 0) state.bubble.life -= dt;
203: 
204:     if (state.phase === "play") {
205:       state.ink = Math.min(state.maxInk, state.ink + 60 * dt);
206:       while (state.spawnIndex < SPAWN_TIMES.length && state.time >= SPAWN_TIMES[state.spawnIndex]) {
207:         spawnBee(state.spawnIndex);
208:         state.spawnIndex++;
209:       }
210:       if (state.time >= DURATION) {
211:         state.phase = "won";
212:         state.winT = 0;
213:         if (!state.ended) {
214:           state.ended = true;
215:           audio.win();
216:           const stars = state.hearts >= 3 ? 3 : state.hearts >= 2 ? 2 : 1;
217:           setTimeout(() => {
218:             api.win(stars, state.blocked, {
219:               note: `${state.hearts} of 3 hearts left. ${state.blocked} bees bonked off your hand-drawn shields.`,
220:             });
221:           }, 700);
222:         }
223:       }
224:     } else if (state.phase === "won") {
225:       state.winT += dt;
226:     } else if (state.phase === "lost") {
227:       state.loseT += dt;
228:     }
229: 
230:     const d = dog();
231: 
232:     // lines age out in the sun
233:     for (const line of state.lines) line.age += dt;
234:     state.lines = state.lines.filter((line) => line.age < LINE_LIFE);
235: 
236:     for (const bee of state.bees) {
237:       bee.phase += dt;
238:       if (state.phase === "play" || state.phase === "lost") {
239:         bee.vy += 92 * dt;
240:         const seek = clamp((d.x - bee.x) * 0.55, -48, 48);
241:         bee.vx += seek * dt;
242:         bee.vx = clamp(bee.vx, -150, 150);
243:         bee.vy = clamp(bee.vy, -80, 290);
244:         bee.x += bee.vx * dt;
245:         bee.y += bee.vy * dt;
246: 
247:         if (bee.x < bee.r) { bee.x = bee.r; bee.vx = Math.abs(bee.vx) * 0.8; }
248:         if (bee.x > stage.w - bee.r) { bee.x = stage.w - bee.r; bee.vx = -Math.abs(bee.vx) * 0.8; }
249: 
250:         collideLines(bee);
251: 
252:         if (dist(bee.x, bee.y, d.x, d.y - d.radius * 0.15) < bee.r + d.radius && state.phase === "play") {
253:           bee.dead = true;
254:           hitDog(bee);
255:         }
256:       }
257:     }
258:     state.bees = state.bees.filter((b) => !b.dead && b.y < stage.h + 40);
259: 
260:     for (const p of state.particles) {
261:       p.life -= dt;
262:       p.x += p.vx * dt;
263:       p.y += p.vy * dt;
264:       p.vy += 250 * dt;
265:       p.vx *= 1 - dt * 1.5;
266:     }
267:     state.particles = state.particles.filter((p) => p.life > 0);
268:   }
