353:     // sunbeam haze
354:     ctx.save();
355:     ctx.globalAlpha = 0.08;
356:     ctx.fillStyle = "#fff";
357:     ctx.beginPath();
358:     ctx.moveTo(w * 0.74, h * 0.17);
