535:     roundRect(ctx, barX, barY, Math.max(2, barW * pct), 8, 4);
536:     ctx.fill();
537:     ctx.fillStyle = "rgba(255,255,255,0.55)";
538:     ctx.font = `900 6.5px ${DISPLAY}`;
