544:   function draw() {
545:     const { ctx } = stage;
546:     const w = stage.w;
547:     const h = stage.h;
548:     ctx.save();
549:     if (state.shake > 0.1) ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
550: 
551:     drawBackground(ctx, w, h);
552:     drawDog(ctx, w, h);
553:     drawBees(ctx);
554:     drawLines(ctx);
555: 
556:     for (const p of state.particles) {
557:       const a = clamp(p.life / p.max, 0, 1);
558:       ctx.globalAlpha = a;
559:       ctx.fillStyle = p.color;
560:       ctx.beginPath();
561:       ctx.arc(p.x, p.y, p.size * a + 0.4, 0, TAU);
562:       ctx.fill();
563:     }
564:     ctx.globalAlpha = 1;
565: 
566:     drawHud(ctx, w, h);
567: 
568:     if (state.flash > 0) {
569:       ctx.fillStyle = `rgba(255, 93, 108, ${state.flash * 0.14})`;
570:       ctx.fillRect(0, 0, w, h);
571:     }
572: 
573:     if (state.phase === "lost") {
574:       ctx.save();
575:       ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
576:       ctx.fillRect(0, 0, w, h);
577:       ctx.fillStyle = "#fff";
578:       ctx.font = `900 ${Math.round(clamp(w * 0.09, 28, 44))}px ${DISPLAY}`;
579:       ctx.textAlign = "center";
580:       ctx.fillText("THE BEES WIN", w / 2, h * 0.42);
581:       ctx.restore();
582:     }
583: 
584:     ctx.restore();
585:   }
