const CAP=4;
function topGroup(t){if(!t.length)return[null,0];const c=t[t.length-1];let n=1;while(n<t.length&&t[t.length-1-n]===c)n++;return[c,n];}
function can(src,dst){if(!src.length||dst.length>=CAP)return false;const [c]=topGroup(src);return !dst.length||dst[dst.length-1]===c;}
function moves(tubes){const out=[];for(let i=0;i<tubes.length;i++)if(tubes[i].length)for(let j=0;j<tubes.length;j++){if(i===j)continue;if(!can(tubes[i],tubes[j]))continue;const [c,n]=topGroup(tubes[i]);const amt=Math.min(n,CAP-tubes[j].length);const next=tubes.map(t=>t.slice());for(let k=0;k<amt;k++){next[i].pop();next[j].push(c);}out.push([i,j,next]);}return out;}
function solved(t){return t.every(t=>t.length===0||(t.length===CAP&&t.every(c=>c===t[0])));}
let best=Infinity,bestPath=null;const seen=new Map();
function key(t){return t.map(a=>a.join('')).join('|');}
function dfs(t,depth,path){if(depth>=best)return;if(solved(t)){best=depth;bestPath=path;return;}const k=key(t);if(seen.has(k)&&seen.get(k)<=depth)return;seen.set(k,depth);for(const [i,j,next] of moves(t))dfs(next,depth+1,[...path,[i+1,j+1]]);}
