const COLS = 13;
const ROWS = 21;
const GOAL = 15;

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);
  const input = createKeyboard();

  const state = {
    phase: "intro",
    time: 0,
    intro: 1.2,
    snake: [],
    dir: { x: 1, y: 0 },
    queued: { x: 1, y: 0 },
    apples: 0,
    grow: 0,
    stepTimer: 0,
    stepInterval: 0.19,
    apple: null,
    particles: [],
    floats: [],
    shake: 0,
    flash: 0,
    winT: 0,
    deadT: 0,
    ended: false,
    deathReason: "",
    layout: null,
  };

  function layout() {
    const pad = 16;
    const hudTop = 64;
    const availW = Math.max(120, stage.w - pad * 2);
    const availH = Math.max(160, stage.h - hudTop - 22);
    const cell = clamp(Math.min(availW / COLS, availH / ROWS), 11, 34);
    const bw = cell * COLS;
    const bh = cell * ROWS;
    return {
      cell, bw, bh,
      ox: (stage.w - bw) / 2,
      oy: hudTop + (availH - bh) / 2,
      w: stage.w, h: stage.h,
    };
  }
  state.layout = layout();

  function cellPos(c) {
    const L = state.layout;
    return { x: L.ox + (c.x + 0.5) * L.cell, y: L.oy + (c.y + 0.5) * L.cell };
  }

  function reset() {
    state.layout = layout();
    const cx = Math.floor(COLS / 2);
    const cy = Math.floor(ROWS / 2);
    state.snake = [
      { x: cx, y: cy },
      { x: cx - 1, y: cy },
      { x: cx - 2, y: cy },
      { x: cx - 3, y: cy },
    ];
    state.dir = { x: 1, y: 0 };
    state.queued = { x: 1, y: 0 };
    state.apples = 0;
    state.grow = 0;
    state.time = 0;
    state.stepTimer = 0;
    state.stepInterval = 0.19;
    state.phase = "intro";
    state.intro = 1.2;
    state.ended = false;
    state.deathReason = "";
    state.particles = [];
    state.floats = [];
    state.winT = 0;
    state.deadT = 0;
    state.shake = 0;
    state.flash = 0;
    spawnApple();
  }

  function spawnApple() {
    const occupied = new Set(state.snake.map(s => `${s.x},${s.y}`));
    const options = [];
    for (let y = 0; y < ROWS; y++) for (let x = 0; x < COLS; x++) {
      if (!occupied.has(`${x},${y}`)) options.push({ x, y });
    }
    // Prefer not adjacent to head? no
    const pick = options[Math.floor(Math.random() * options.length)] || { x: 1, y: 1 };
    state.apple = { x: pick.x, y: pick.y, phase: rand(0, TAU) };
  }
```

