120: export function createLoop(update) {
121:   let raf = 0;
122:   let last = 0;
123:   let running = true;
124:   let paused = false;
125: 
126:   function tick(now) {
127:     if (!running) return;
128:     if (!last) last = now;
129:     const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
130:     last = now;
131:     if (!paused) update(dt);
132:     raf = requestAnimationFrame(tick);
133:   }
134: 
135:   raf = requestAnimationFrame(tick);
136: 
137:   return {
138:     stop() {
139:       running = false;
140:       cancelAnimationFrame(raf);
141:     },
142:     pause() { paused = true; last = 0; },
143:     resume() { paused = false; last = 0; },
144:     get paused() { return paused; },
145:   };
146: }
