148: export function pointOnCanvas(canvas, event) {
149:   const rect = canvas.getBoundingClientRect();
150:   return {
151:     x: ((event.clientX - rect.left) / rect.width) * canvas.clientWidth,
152:     y: ((event.clientY - rect.top) / rect.height) * canvas.clientHeight,
153:   };
