162:     e.preventDefault();
163:     dragging = true;
164:     try { canvas.setPointerCapture(e.pointerId); } catch {}
165:     handlers.down?.(local(e), e);
166:   };
167:   const move = (e) => {
168:     const p = local(e);
169:     if (dragging || e.pointerType === "mouse") handlers.move?.(p, e);
170:   };
171:   const up = (e) => {
172:     if (!dragging) return;
173:     dragging = false;
174:     try { canvas.releasePointerCapture(e.pointerId); } catch {}
175:     handlers.up?.(local(e), e);
176:   };
177:   const leave = (e) => {
178:     handlers.leave?.(local(e), e);
179:   };
180:   const cancel = (e) => {
181:     if (!dragging) return;
182:     dragging = false;
183:     handlers.up?.(local(e), e);
184:   };
