186:   canvas.addEventListener("pointerdown", down);
187:   canvas.addEventListener("pointermove", move);
188:   canvas.addEventListener("pointerup", up);
189:   canvas.addEventListener("pointercancel", cancel);
190:   canvas.addEventListener("pointerleave", leave);
191:   canvas.addEventListener("contextmenu", (e) => e.preventDefault());
